import React,{useState} from 'react';import {createRoot} from 'react-dom/client';import {COMPONENT_TYPES,createSurfaceSession,SurfaceRenderer,type DataProjection,type SurfaceProposal,type ActionIntent} from './index.ts';import './styles.css';import './demo.css';
const session=createSurfaceSession({sessionId:'offlineDemo',surfaceId:'work',provenance:{sourceLabel:'Lokaler Demovorschlag',runLabel:'Fixture, keine Live-Telemetrie'},registeredComponents:new Set(COMPONENT_TYPES),actions:new Map([['inspect',{kind:'navigate',label:'Aufgaben im Host ansehen',target:{view:'tasks'}}],['review',{kind:'suggest',label:'Skillprüfung vorbereiten',target:{topic:'review-skill',entityId:'offline-skill'}}]])});
const proposal:SurfaceProposal={schema:'cue.command-mesh.surface/v1',catalogVersion:'cue.readonly/v1',sessionId:'offlineDemo',surfaceId:'work',baseRevision:0,rootId:'root',components:[
{id:'root',type:'Group',props:{layout:'split'},children:['intro','count','tasks','sources','graph','skills','events','status']},
{id:'intro',type:'Text',props:{text:'Eine flexible Arbeitsfläche für den nächsten Schritt. Dieser Text ist ein Vorschlag und kann keine Hostrechte verändern.'}},
{id:'count',type:'Metric',props:{label:'Offene Beispielaufgaben'},dataRef:'count'},
{id:'tasks',type:'TaskList',props:{label:'Lokale Aufgabenprojektion'},dataRef:'tasks',actionRef:'inspect'},
{id:'sources',type:'SourceList',props:{label:'Quellen im Snapshot'},dataRef:'sources'},
{id:'graph',type:'GraphSlot',props:{label:'Gemeinsamer Graph · Hostslot'},dataRef:'graph'},
{id:'skills',type:'SkillSuggestionSlot',props:{label:'Skillprüfung · Hostslot'},dataRef:'skills',actionRef:'review'},
{id:'events',type:'EventList',props:{label:'Zurückbehaltene Ereignisse'},dataRef:'events'},
{id:'status',type:'Status',props:{label:'Externer Agentenstatus'},dataRef:'external'}]};
session.submit(JSON.stringify(proposal));
const fixtures:ReadonlyMap<string,DataProjection>=new Map([
['count',{kind:'metric',state:'known',value:2}],['tasks',{kind:'tasks',state:'known',value:[{id:'t1',label:'Freigabegrenze prüfen',detail:'Beispieldaten · offen'},{id:'t2',label:'Android-Abnahme planen',detail:'Beispieldaten · noch nicht ausgeführt'}]}],['sources',{kind:'sources',state:'known',value:[{id:'s1',label:'Interner Oberflächenvertrag v1',detail:'Gebündelt · keine URL geladen'}]}],['graph',{kind:'graph',state:'known',value:{label:'GraphExplorer wird vom Host eingebettet'}}],['skills',{kind:'skills',state:'known',value:{label:'Skill Inspector wird vom Host eingebettet'}}],['events',{kind:'events',state:'stale',value:[{id:'e1',label:'Offline-Demo vorbereitet',detail:'Statischer Verlauf, keine Zustandsrekonstruktion'}]}],['external',{kind:'status',state:'unknown'}]
]);
const demoSlots:NonNullable<React.ComponentProps<typeof SurfaceRenderer>["slots"]>={Graph:({value})=><div className="demo-slot"><strong>2D / 3D · bestehendes Hostmodul</strong><p>{(value as {label:string}).label}</p><small>Kein Graphnachbau. Hier bleibt der geprüfte GraphExplorer zuständig.</small></div>,Skills:({value})=><div className="demo-slot"><strong>Offline-Skillkern · bestehendes Hostmodul</strong><p>{(value as {label:string}).label}</p><small>Keine Ausführung, keine Authentifizierung und keine neu erteilte Berechtigung.</small></div>};
function Demo(){const [intent,setIntent]=useState<ActionIntent|null>(null),[missing,setMissing]=useState(false);function layout(mode:'stack'|'split'|'focus'){const next=structuredClone(proposal);next.baseRevision=session.getSnapshot().revision;const group=next.components[0];if(group.type==='Group')group.props={layout:mode,...(mode==='focus'?{focusId:'tasks'}:{})};session.submit(JSON.stringify(next))}
return <div className="demo"><header className="demo-shell"><div><small>CUE COMMAND MESH · LOKALER KANDIDAT</small><h1>Arbeitsflächen mit klaren Grenzen</h1></div><span className="demo-offline">Offline-Demo · nicht verbunden</span></header><main><section className="demo-controls" aria-label="Vertrauenswürdige Hoststeuerung"><h2>Hoststeuerung</h2><p>Navigation, Sicherheitsanzeigen und jede echte Freigabe bleiben hier in der festen Hülle. Die Oberfläche darunter enthält nur Vorschläge.</p><div className="demo-buttons">{(['stack','split','focus'] as const).map(mode=><button key={mode} onClick={()=>layout(mode)}>{mode}</button>)}<button onClick={()=>setMissing(v=>!v)}>Hostdaten {missing?'zeigen':'entfernen'}</button><button onClick={()=>session.submit(JSON.stringify({...proposal,baseRevision:session.getSnapshot().revision,approved:true}))}>Ungültiges Approval-Feld testen</button></div><p role="status">{intent?`Host empfängt ${intent.kind} · ${intent.actionRef} · Revision ${intent.surfaceRevision}. Keine Aktion ausgeführt.`:'Noch kein Intent. Die Demo führt keine Fachaktion aus.'}</p></section><SurfaceRenderer session={session} data={missing?new Map():fixtures} onIntent={i=>setIntent(i)} slots={demoSlots}/><footer>Interner UI-Vertrag v1 · Keine A2UI-/AG-UI-/MCP-Kompatibilitätsbehauptung · Android/TalkBack/GPU noch separat abzunehmen</footer></main></div>}
createRoot(document.getElementById('root')!,{onCaughtError:()=>{/* Host-owned redacted error telemetry would live here. */}}).render(<Demo/>);
